		}
		break;
	case GL_LINE_STRIP:
#if TGL_FEATURE_GL_POLYGON == 1
	case GL_LINE_LOOP:
#endif
		switch (n) {
		case 1: {
			c->vertex[2] = c->vertex[0];
		} break;
		case 2: {
			gl_draw_line(&c->vertex[0], &c->vertex[1]);
			c->vertex[0] = c->vertex[1];
			n = 1;
		} break;
		default:
			break;
		};
		break;
	case GL_TRIANGLES:
		if (n == 3) {
			gl_draw_triangle(&c->vertex[0], &c->vertex[1], &c->vertex[2]);
			n = 0;
		}
		break;
	case GL_TRIANGLE_STRIP:
		if (cnt >= 3) {
			if (n == 3)
				n = 0;
			/* needed to respect triangle orientation */
			switch (cnt & 1) {
			case 0:
				gl_draw_triangle(&c->vertex[2], &c->vertex[1], &c->vertex[0]);
				break;
			default:
			case 1:
				gl_draw_triangle(&c->vertex[0], &c->vertex[1], &c->vertex[2]);
				break;
			}
		}
		break;
	case GL_TRIANGLE_FAN:
		if (n == 3) {
			gl_draw_triangle(&c->vertex[0], &c->vertex[1], &c->vertex[2]);
			c->vertex[1] = c->vertex[2];
			n = 2;
		}
		break;

	case GL_QUADS:
		if (n == 4) {
			c->vertex[2].edge_flag = 0;
			gl_draw_triangle(&c->vertex[0], &c->vertex[1], &c->vertex[2]);
			c->vertex[2].edge_flag = 1;
			c->vertex[0].edge_flag = 0;
			gl_draw_triangle(&c->vertex[0], &c->vertex[2], &c->vertex[3]);
			n = 0;
		}
		break;

	case GL_QUAD_STRIP:
		if (n == 4) {
			gl_draw_triangle(&c->vertex[0], &c->vertex[1], &c->vertex[2]);
			gl_draw_triangle(&c->vertex[1], &c->vertex[3], &c->vertex[2]);
			for (i = 0; i < 2; i++)
				c->vertex[i] = c->vertex[i + 2];
			n = 2;
		}
		break;

#if TGL_FEATURE_GL_POLYGON == 1
	case GL_POLYGON:
